untime=$($Result.runtime_mode) base=$($Result.base)")}catch{Log ("Connect failed: $($_.Exception.Message)")};RefreshProduct});(Control 'DisconnectButton').Add_Click({try{[void](Api '/api/disconnect' 'POST' @{} 15);Log 'Disconnected'}catch{Log $_.Exception.Message};RefreshProduct});(Control 'PublicIpButton').Add_Click({try{$Result=Api '/api/public-ip' -Timeout 12;Log ("Public VPN exit: $($Result.public_ip)")}catch{Log $_.Exception.Message}});$DnsButton.Add_Click({try{$Result=Api '/api/dns/retest' 'POST' @{} 90;Log ("DNS winner: $($Result.winner.address) $($Result.winner.latency_ms)ms")}catch{Log $_.Exception.Message};RefreshDnsPolicy;RefreshProduct});$DnsRefreshButton.Add_Click({RefreshDnsPolicy;RefreshProduct});$DnsSaveButton.Add_Click({try{$Body=@{mode=(ComboTag $DnsModeCombo 'home');protocol=(ComboTag $DnsProtocolCombo 'udp');host=[string]$DnsHostBox.Text;port=([int]([string]$DnsPortBox.Text));server_name=[string]$DnsServerBox.Text;path=[string]$DnsPathBox.Text};$Result=Api '/api/dns/policy' 'POST' $Body 10;Log ("DNS policy saved for next connection: $($Result.mode) $($Result.host)")}catch{Log ("DNS policy failed: $($_.Exception.Message)")};RefreshDnsPolicy;RefreshProduct});$DnsPresetCombo.Add_SelectionChanged({$Tag=ComboTag $DnsPresetCombo 'manual';$Map=@{cf4=@('1.1.1.1','cloudflare-dns.com');cf6=@('2606:4700:4700::1111','cloudflare-dns.com');g4=@('8.8.8.8','dns.google');g6=@('2001:4860:4860::8888','dns.google');q4=@('9.9.9.9','dns.quad9.net');q6=@('2620:fe::fe','dns.quad9.net')};if($Map.ContainsKey($Tag)){$DnsHostBox.Text=$Map[$Tag][0];$DnsServerBox.Text=$Map[$Tag][1]}});(Control 'EmergencyButton').Add_Click({try{[void](Api '/api/emergency-stop' 'POST' @{} 15);Log 'Emergency stop completed'}catch{Log $_.Exception.Message};RefreshProduct});(Control 'PairNodeButton').Add_Click({try{ShowPairNodeDialog}catch{Log ("Pairing failed: $($_.Exception.Message)")}});(Control 'ImportNodeButton').Add_Click({try{$Picker=New-Object Microsoft.Win32.OpenFileDialog;$Picker.Title='Import Router VPN or external node';$Picker.Filter='Router VPN / external JSON (*.json)|*.json|All files (*.*)|*.*';if($Picker.ShowDialog($Window)){$Bytes=[IO.File]::ReadAllBytes($Picker.FileName);if($Bytes.Length-gt(32MB)){throw 'Node JSON is larger than 32 MiB.'};$Imported=ImportAnyNode $Bytes;Log ("Imported $($Imported.kind) node: $($Imported.result.profile.name)");RefreshProduct}}catch{Log ("Import failed: $($_.Exception.Message)")}});(Control 'ExternalDirectButton').Add_Click({try{ConnectExternal $false}catch{Log ("External direct failed: $($_.Exception.Message)")};RefreshProduct});(Control 'ExternalViaEntryButton').Add_Click({try{ConnectExternal $true}catch{Log ("External via entry failed: $($_.Exception.Message)")};RefreshProduct});(Control 'DeleteNodeButton').Add_Click({try{$Profile=SelectedNode;$Answer=[System.Windows.MessageBox]::Show("Remove linked node '$($Profile.name)' from this app?",'Router VPN',[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning);if($Answer-eq[System.Windows.MessageBoxResult]::Yes){[void](Api '/api/profile/delete' 'POST' @{id=[string]$Profile.id} 10);Log ("Removed node $($Profile.name)");RefreshProduct}}catch{Log ("Remove failed: $($_.Exception.Message)")}});(Control 'SelectNodeButton').Add_Click({try{$Profile=SelectedNode;[void](Api '/api/profile/select' 'POST' @{id=[string]$Profile.id} 10)}catch{Log $_.Exception.Message};RefreshProduct});(Control 'LatencyButton').Add_Click({try{$Profile=SelectedNode;$Result=Api '/api/profile/latency' 'POST' @{id=[string]$Profile.id;samples=50} 180;Log ("Latency median=$($Result.median_ms)ms p90=$($Result.p90_ms)ms")}catch{Log $_.Exception.Message};RefreshProduct});$RouterCombo.Add_SelectionChanged({if($RouterCombo.SelectedValue){try{[void](Api '/api/profile/select' 'POST' @{id=[string]$RouterCombo.SelectedValue} 10)}catch{};RefreshDnsPolicy;RefreshProduct}});(Control 'TutorialButton').Add_Click({[System.Windows.MessageBox]::Show('Install once. In Nodes / Map, pair with a 6-digit one-time code or import Router VPN/external schema-v3 JSON. Order nodes by current/recent, last used, lowest measured latency or name. Automatic lowest-latency choice requires real 50-sample measurements on at least two usable nodes. Modes shows layers, latency/traffic/speed estimates and exact live readiness reason. DNS supports Home/Fastest/Custom/DoT/DoH/DoH3/Rescue; benchmark values are real home-node DNS query RTT. Highlight an external exit for direct connect, or choose a different entry in Advanced and use External via Advanced entry. Exact public-exit proof is mandatory; unsupported protocol/hop combinations stay rejected.','Router VPN native onboarding')|Out-Null})
